/* =========================
   TESTIMONIAL HOS V2 (ảnh)
========================= */
.testimonial-hos-v2 {
    position: relative;
    overflow: hidden;
    padding: 48px 0 56px;
    background-color: #f4fcf9;
}

.testimonial-hos-v2__inner {
    position: relative;
    z-index: 1;
    background-image: url(/assets/img/testimonial/Testimonial-bg.png);
    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;
    padding: 40px 24px 48px;
}

.testimonial-hos-v2 .container-fluid {
    max-width: 1400px;
    margin: 0 auto;
    padding-left: 24px;
    padding-right: 24px;
}

.testimonial-hos-v2__intro {
    padding-right: 12px;
    margin-bottom: 24px;
}

.testimonial-hos-v2__text-img {
    display: block;
    max-width: 100%;
    height: auto;
}

.testimonial-hos-v2__slider-col {
    padding-left: 8px;
    overflow: hidden;
}

.testimonial-hos-v2-slider {
    margin: 0 -12px;
    max-width: none;
}

.testimonial-hos-v2-slider .slick-list {
    overflow: visible;
    padding: 24px 0 32px !important;
}

.testimonial-hos-v2__slide {
    padding: 0 12px;
    outline: none;
}

.testimonial-hos-v2__card-img {
    display: block;
    width: 100%;
    max-width: 340px;
    height: auto;
    margin: 0 auto;
    transition: transform 0.35s ease, opacity 0.35s ease;
    transform: scale(0.88);
    opacity: 0.72;
}

.testimonial-hos-v2-slider .slick-center .testimonial-hos-v2__card-img {
    transform: scale(1);
    opacity: 1;
}

.testimonial-hos-v2-slider .slick-track {
    display: flex;
    align-items: center;
}

@media (min-width: 992px) {
    .testimonial-hos-v2__intro {
        margin-bottom: 0;
        padding-right: 28px;
    }

    .testimonial-hos-v2__card-img {
        max-width: 320px;
    }

    .testimonial-hos-v2-slider .slick-center .testimonial-hos-v2__card-img {
        max-width: 360px;
    }
}

@media (max-width: 991px) {
    .testimonial-hos-v2 {
        padding: 32px 0 40px;
    }

    .testimonial-hos-v2__inner {
        padding: 28px 16px 36px;
    }

    .testimonial-hos-v2__intro {
        text-align: center;
        padding-right: 0;
    }

    .testimonial-hos-v2__text-img {
        margin: 0 auto;
        max-width: 420px;
    }

    .testimonial-hos-v2__slider-col {
        padding-left: 0;
    }

    .testimonial-hos-v2__card-img {
        max-width: 300px;
    }
}

